  const [location] = useLocation();
  const [collapsed, setCollapsed] = useState(false);

  const navigation = [
    {
      name: "Dashboard",
      href: "/admin",
      icon: Home,
      current: location === "/admin"
    },
    {
      name: "Cities",
      href: "/admin/cities",
      icon: MapPin,
      current: location === "/admin/cities"
    },
    {
      name: "Kitchens",
      href: "/admin/restaurants", 
      icon: Building,
      current: location === "/admin/restaurants"
    },
    {
      name: "Features",
      href: "/admin/features",
      icon: Star,
      current: location === "/admin/features"
    },
    {
      name: "Statistics",
      href: "/admin/stats",
      icon: BarChart3,
      current: location === "/admin/stats"
    },
    {
      name: "Footer Pages",
      href: "/admin/footer-pages",
      icon: FileText,
      current: location === "/admin/footer-pages"
    },
    {
      name: "Hero Section",
      href: "/admin/hero",
      icon: Image,
      current: location === "/admin/hero"
    },
    {
      name: "Kitchen Registrations",
      href: "/admin/cook-registrations",
      icon: ChefHat,
      current: location === "/admin/cook-registrations"
    },
    {
      name: "Settings",
      href: "/admin/settings",
      icon: Settings,
      current: location === "/admin/settings"
    }
  ];

  return (
    <div className={cn(
      "bg-gray-900 text-white transition-all duration-300 ease-in-out",
      collapsed ? "w-16" : "w-64"
    )}>
      <div className="flex flex-col h-full">
        {/* Header */}
        <div className="flex items-center justify-between p-4 border-b border-gray-700">
          {!collapsed && (
            <div className="flex items-center space-x-2">
              <Shield className="h-6 w-6 text-orange-500" />
              <span className="text-lg font-semibold">Admin Panel</span>
            </div>
          )}
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setCollapsed(!collapsed)}
            className="text-gray-400 hover:text-white hover:bg-gray-800"
          >
            {collapsed ? <Menu className="h-4 w-4" /> : <X className="h-4 w-4" />}
          </Button>
        </div>

        {/* Navigation */}
