// Define the gtag function globally
declare global {
  interface Window {
    dataLayer: any[];
    gtag: (...args: any[]) => void;
  }
}

// Initialize Google Analytics
export const initGA = () => {
  const measurementId = import.meta.env.VITE_GA_MEASUREMENT_ID;

  if (!measurementId) {
    console.warn('Missing required Google Analytics key: VITE_GA_MEASUREMENT_ID');
    return;
  }

  // Add Google Analytics script to the head
  const script1 = document.createElement('script');
  script1.async = true;
  script1.src = `https://www.googletagmanager.com/gtag/js?id=${measurementId}`;
  document.head.appendChild(script1);

  // Initialize gtag
  const script2 = document.createElement('script');
  script2.textContent = `
    window.dataLayer = window.dataLayer || [];
    function gtag(){dataLayer.push(arguments);}
    gtag('js', new Date());
    gtag('config', '${measurementId}');
  `;
  document.head.appendChild(script2);
};

// Track page views - useful for single-page applications
export const trackPageView = (url: string) => {
  if (typeof window === 'undefined' || !window.gtag) return;

  const measurementId = import.meta.env.VITE_GA_MEASUREMENT_ID;
  if (!measurementId) return;

  window.gtag('config', measurementId, {
    page_path: url
  });
};

// Track events with cook_id support
export const trackEvent = (
  action: string, 
  category?: string, 
  label?: string, 
  value?: number,
  cookId?: number
) => {
  if (typeof window === 'undefined' || !window.gtag) return;

  window.gtag('event', action, {
    event_category: category,
    event_label: label,
    value: value,
    custom_parameters: {
      cook_id: cookId
    }
  });
};

// Send analytics to backend API
export const sendAnalyticsToAPI = async (
  action: string,
  category?: string,
  label?: string,
  value?: number,
  additionalData?: any
) => {
  try {
    const response = await fetch('/api/analytics/track', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${localStorage.getItem('chef_token')}`
      },
      body: JSON.stringify({
        action,
        category,
        label,
        value,
        additionalData,
        timestamp: new Date().toISOString()
      })
    });

    if (!response.ok) {
      console.error('Failed to send analytics to API');
    }
  } catch (error) {
    console.error('Error sending analytics to API:', error);
  }
};
